        or ("tareas_repetitivas"."repeticion" = 'semanal' and cardinality("tareas_repetitivas"."dias_semana") between 1 and 7 and "tareas_repetitivas"."dia_del_mes" is null and "tareas_repetitivas"."mes" is null and "tareas_repetitivas"."cada_dias" is null and "tareas_repetitivas"."fecha_inicio" is null)
