        or ("tareas_repetitivas"."repeticion" = 'anual' and "tareas_repetitivas"."dia_del_mes" is not null and "tareas_repetitivas"."mes" is not null and "tareas_repetitivas"."dias_semana" is null and "tareas_repetitivas"."cada_dias" is null and "tareas_repetitivas"."fecha_inicio" is null));